    eG1_TDO G1_TDO : 1;
    // read-write - Access Group 1 Secure Memory Blobs
    eG1_SMBLOB G1_SMBLOB : 1;
    // read-write - Access Group 2 Read
    eG2_READ G2_READ : 1;
    // read-write - Access Group 2 Write
    eG2_WRITE G2_WRITE : 1;
    // read-write - Access Group 2 Trusted Descriptor Override
    eG2_TDO G2_TDO : 1;
    // read-write - Access Group 2 Secure Memory Blobs
    eG2_SMBLOB G2_SMBLOB : 1;
