    // read-write - SMAG LOCK bit
    eSMAG_LCK SMAG_LCK : 1;
    // read-write - SMAP LOCK bit
    eSMAP_LCK SMAP_LCK : 1;
    // read-write - Public Security Parameters
    ePSP PSP : 1;
    // read-write - Critical Security Parameters
    eCSP CSP : 1;
