    // read-only - PKHA (Public Key) Error Interrupt asserted.
    ePEI PEI : 1;
    // read-only - MDHA (hashing) Error Interrupt asserted.
    eMEI MEI : 1;
    // read-only - CRCA Error Interrupt asserted.
