// DECO0 Debug DECO Register
union D0DDR {
  
  // Checking Trusted
  enum class eCT : uint32_t {
    // This DECO is NOTcurrently generating the signature of a Trusted Descriptor.
    eNOT_CHECKING = 0,
    // This DECO is currently generating the signature of a Trusted Descriptor.
    eCHECKING = 1,
  };
  
  // Burster Read Busy
  enum class eBRB : uint32_t {
    // The READ machine in the Burster is not busy.
    eNOT_BUSY = 0,
    // The READ machine in the Burster is busy.
    eBUSY = 1,
  };
  
  // Burster Write Busy
  enum class eBWB : uint32_t {
    // The WRITE machine in the Burster is not busy.
    eNOT_BUSY = 0,
    // The WRITE machine in the Burster is busy.
    eBUSY = 1,
  };
  
  // No Command
  enum class eNC : uint32_t {
    // This DECO is currently executing a command.
    eCMD_EXEC = 0,
    // This DECO is not currently executing a command.
    eNO_CMD_EXEC = 1,
  };
  
  // Took Non-local JUMP
  enum class eNLJ : uint32_t {
    // The original job descriptor running in this DECO has not caused another job descriptor to be executed.
    eORIGINAL_DESC = 0,
    // The original job descriptor running in this DECO has caused another job descriptor to be executed.
    eNON_LOCAL_DECR = 1,
  };
  
  // Protocol running. PTCL_RUN=1 indicates that a protocol is running in this DECO.
  enum class ePTCL_RUN : uint32_t {
    // No protocol is running in this DECO.
    eNOT_RUNNING = 0,
    // A protocol is running in this DECO.
    eRUNNING = 1,
  };
  
  // Non-SEQ DID Select. This indicates which type of DID is being used for Non-SEQ commands:
  enum class eNSEQLSEL : uint32_t {
    // SEQ DID
    eSEQ_DID = 1,
    // Non-SEQ DID
    eNONSEQ_DID = 2,
    // Trusted DID
    eTRUSTED_DID = 3,
  };
  
  // SEQ DID Select. This indicates which type of DID is being used for SEQ commands:
  enum class eSEQLSEL : uint32_t {
    // SEQ DID
    eSEQ_DID = 1,
    // Non-SEQ DID
    eNONSEQ_DID = 2,
    // Trusted DID
    eTRUSTED_DID = 3,
  };
  
  // Shared Descriptor
  enum class eSD : uint32_t {
    // This DECO has not received a shared descriptor from another DECO.
    eNO_SD_RCVD = 0,
    // This DECO has received a shared descriptor from another DECO.
    eSD_RCVD = 1,
  };
  
  // Valid
  enum class eVALID : uint32_t {
    // No descriptor is currently running in this DECO.
    eNO_DESC_RUNNING = 0,
    // There is currently a descriptor running in this DECO.
    eDESC_RUNNING = 1,
  };
  
  // Bit field definition.
  struct {
    // read-only - Checking Trusted
    eCT CT : 1;
    // read-only - Burster Read Busy
    eBRB BRB : 1;
    // read-only - Burster Write Busy
    eBWB BWB : 1;
    // read-only - No Command
    eNC NC : 1;
    // read-only - Command Stage Aux
    uint32_t CSA : 1;
    // read-only - Command Stage
    uint32_t CMD_STAGE : 3;
    // read-only - Command Index
    uint32_t CMD_INDEX : 6;
    // read-only - Took Non-local JUMP
    eNLJ NLJ : 1;
    // read-only - Protocol running. PTCL_RUN=1 indicates that a protocol is running in this DECO.
    ePTCL_RUN PTCL_RUN : 1;
    // read-only - PDB Stall State
    uint32_t PDB_STALL : 2;
    // read-only - PDB Writeback State. Lower two bits of the state machine that tracks the state of PDB writebacks.
    uint32_t PDB_WB_ST : 2;
    // read-only - DECO State. The current state of DECO's main state machine.
    uint32_t DECO_STATE : 4;
    // read-only - Non-SEQ DID Select. This indicates which type of DID is being used for Non-SEQ commands:
    eNSEQLSEL NSEQLSEL : 2;
    // read-only - SEQ DID Select. This indicates which type of DID is being used for SEQ commands:
    eSEQLSEL SEQLSEL : 2;
    // read-only - DMA Transaction Count
    uint32_t TRCT : 2;
    // read-only - Shared Descriptor
    eSD SD : 1;
    // read-only - Valid
    eVALID VALID : 1;
  } bits;
  
  // Full 32-bit register value.
  uint32_t value;

  inline void Reset() volatile { this->value = 0x00000000; }
  static inline volatile D0DDR &ref() { return *reinterpret_cast<volatile D0DDR*>(0x404C0E04); }
};

